// ===== Representante comercial do bolsão (encerramento) =====
// O responsável de cada bolsão vem da coluna "Responsável" da lista "Matriz Bolsões" (SharePoint).
// O bolsão do encerramento vem da coluna "Bolsão" (linha "Bolsão:" do e-mail); se vier vazio, tenta pelo endereço.
const REPRESENTANTES = {
  'exemplo1@exemplo.com':  '5511999999999',   // Responsável A
  'exemplo2@exemplo.com': '5511999999999',   // Responsável B
};
// Recebe sempre. Também é o único destino quando o bolsão não é encontrado na Matriz.
const SEMPRE = [
  '5511999999999',          // Responsável pela automação
];
// EM TESTE: true = cada representante é trocado pelo número de teste abaixo.
// Para colocar em produção, troque para false.
const MODO_TESTE = true;
const NUMEROS_TESTE = {
  'exemplo1@exemplo.com':  '5511999999999',   // bolsões do Responsável A → Responsável pela automação
  'exemplo2@exemplo.com': '5511999999999',   // bolsões da Ana → Responsável pela automação
};

const norm = s => ' ' + String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\b(rua|r|av|avenida|alameda|al|praca|travessa|estrada|bolsao)\b/g, ' ')
  .replace(/\s+/g, ' ').trim() + ' ';

// Procura o bolsão na Matriz (ignora acentos, maiúsculas e "Rua", "Av." etc.)
const acharBolsao = (textos, matriz) => {
  for (const t of textos) {
    const alvo = norm(t);
    if (alvo.trim().length < 3) continue;
    const achados = (matriz || []).filter(b => {
      const n = norm(b.Title);
      return n.trim().length >= 3 && (alvo.includes(n) || n.includes(alvo));
    });
    if (achados.length) return achados.sort((a, b) => norm(b.Title).length - norm(a.Title).length)[0];
  }
  return null;
};

const bolsaoDoItem = f => f.Bols_x00e3_o || f.Bolsao || '';

const representante = (f, resposta) => {
  const lista = resposta && Array.isArray(resposta.value) ? resposta.value : null;
  const b = lista ? acharBolsao([bolsaoDoItem(f), f.Title], lista) : null;
  const resp = (b && b.Respons_x00e1_vel) || {};
  const email = String(resp.EMail || '').toLowerCase();
  const tel = MODO_TESTE ? NUMEROS_TESTE[email] : REPRESENTANTES[email];
  let aviso = '';
  if (!lista) aviso = 'Não foi possível consultar a Matriz Bolsões. Mensagem enviada só para o responsável pela automação.';
  else if (!b) aviso = `Bolsão "${bolsaoDoItem(f) || 'não informado'}" não encontrado na Matriz Bolsões. Mensagem enviada só para o responsável pela automação.`;
  else if (!tel) aviso = `Responsável "${resp.Title || 'não preenchido'}" do bolsão ${b.Title} sem WhatsApp cadastrado na automação.`;
  if (MODO_TESTE && tel) aviso = `MODO TESTE – em produção esta mensagem iria para ${resp.Title} (${REPRESENTANTES[email] || 'sem número'}).`;
  return {
    bolsao: b ? b.Title : (bolsaoDoItem(f) || null),
    representante: tel ? (resp.Title || null) : null,
    responsavel: resp.Title || null,   // nome do responsável na Matriz (aparece na mensagem)
    // em teste vai só para o número de teste do representante; em produção, representante + SEMPRE
    numeros: MODO_TESTE ? (tel ? [tel] : SEMPRE) : (tel ? [tel] : []).concat(SEMPRE),
    aviso,
  };
};

const valido = n => String(n).replace(/\D/g, '');
const listaChat = arr => [...new Set(arr.map(valido).filter(n => n.length >= 12 && n.length <= 13))].map(n => n + '@c.us');


// ----- Padrão das mensagens (igual à adesão) -----
const dataBR = d => { if (!d) return 'Não informada'; const dt = DateTime.fromISO(String(d)).setZone('America/Sao_Paulo'); return dt.isValid ? dt.toFormat('dd/MM/yyyy') : String(d); };
const blocoEncerramento = (f, bolsao) => [
  `🏘️ *Bolsão:* ${bolsao || f.Bols_x00e3_o || f.Bolsao || 'Não informado'}`,
  '',
  `👤 *Cliente:* ${f.NomedoCliente || 'Não informado'}`,
  `📍 *Endereço:* ${f.Title || 'Não informado'}`,
  `📞 *Telefone:* ${f.ContatodoCliente || 'Não informado'}`,
  `📧 *E-mail:* ${f.E_x002d_MaildoCliente || 'Não informado'}`,
  `📝 *Motivo:* ${f.Motivo || 'Não informado'}`,
  `📅 *Data do encerramento:* ${dataBR(f.AvisoPrevio)}`,
].join('\n');

const TIMEZONE = 'America/Sao_Paulo';

function dataLocal(date) {
  const partes = new Intl.DateTimeFormat('en-CA', {
    timeZone: TIMEZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);

  const get = (tipo) => partes.find(p => p.type === tipo).value;

  return `${get('year')}-${get('month')}-${get('day')}`;
}

function diaUTC(data) {
  const [ano, mes, dia] = data.split('-').map(Number);
  return Date.UTC(ano, mes - 1, dia);
}

function formatarDataISO(dataISO) {
  if (!dataISO) return 'Não informado';

  return DateTime
    .fromISO(dataISO)
    .setZone(TIMEZONE)
    .toFormat('dd/MM/yyyy');
}

const hojeTexto = dataLocal(new Date());
const hoje = diaUTC(hojeTexto);

const montarLinha = (item, r) => {
  const fields = item.json.fields ?? item.json;

  const limiteOriginal = new Date(fields.DataLimiteComercial);
  const limiteTexto = dataLocal(limiteOriginal);
  const limite = diaUTC(limiteTexto);

  const diasRestantes = Math.max(
    0,
    Math.round((limite - hoje) / (1000 * 60 * 60 * 24))
  );

  const nomeCliente = fields.NomedoCliente || 'Não informado';
  const endereco = fields.Title || 'Não informado';
  const motivo = fields.Motivo || 'Não informado';
  const email = fields.E_x002d_MaildoCliente || 'Não informado';
  const telefone = fields.ContatodoCliente || 'Não informado';

  const avisoPrevio = formatarDataISO(fields.AvisoPrevio);
  const prazoComercial = formatarDataISO(fields.DataLimiteComercial);

  return `${blocoEncerramento(fields, r.bolsao)}
⏳ *Prazo para recuperação:* ${prazoComercial} (${diasRestantes} ${diasRestantes === 1 ? 'dia restante' : 'dias restantes'})`;
};

// Um lembrete por destinatário, só com os clientes dos bolsões dele
const matriz = $('Buscar Matriz Bolsões').first().json;
const porChat = {};
for (const item of $('Verificar se a data venceu').all()) {
  const f = item.json.fields ?? item.json;
  const r = representante(f, matriz);
  for (const chatId of listaChat(r.numeros)) (porChat[chatId] = porChat[chatId] || []).push(montarLinha(item, r));
}
return Object.entries(porChat).map(([chatId, linhas]) => ({ json: {
  chatId,
  mensagem: `🔔 *LEMBRETE – COMERCIAL*\n\nClientes ainda dentro do prazo para tentativa de recuperação:\n\n${linhas.join('\n\n────────────────────\n\n')}\n\n📌 *Pendência:*\nRegistrar o resultado na enquete de cada cliente.`,
} }));
